problems.template:
SELECT region, order_id, amount,
  {{1}}() OVER ({{2}} region ORDER BY amount {{3}}) AS rn
FROM sales;

solutions:
SELECT region, order_id, amount,
  row_number() OVER (PARTITION BY region ORDER BY amount DESC) AS rn
FROM sales;

